// Minimaler Mock der Bedrock-Skript-API für Offline-Simulation.
export const InputPermissionCategory = { Camera: 1, Movement: 2, LateralMovement: 4, Sneak: 5, Jump: 6 };
export const GameMode = { Survival: "Survival", Creative: "Creative", Adventure: "Adventure", Spectator: "Spectator" };

class Signal { constructor() { this.subs = []; } subscribe(cb) { this.subs.push(cb); return cb; } emit(ev) { for (const s of this.subs) s(ev); } }

export const world = {
  afterEvents: { entitySpawn: new Signal(), entityHurt: new Signal(), playerSpawn: new Signal(), playerLeave: new Signal(), entityDie: new Signal() },
  players: [],
  props: {},
  getAllPlayers() { return this.players; },
  getDynamicProperty(k) { return this.props[k]; },
  setDynamicProperty(k, v) { this.props[k] = v; },
};
export const system = {
  intervals: [],
  runInterval(cb, n = 1) { this.intervals.push({ cb, n }); return this.intervals.length; },
  tick(t) { for (const i of this.intervals) if (t % i.n === 0) i.cb(); },
};
